import multiprocessing
import math
import time

def burn():
    # Intensive mathematical operations in a loop
    while True:
        _ = math.factorial(2000)

if __name__ == '__main__':
    cores = 10
    print(f"Starting {cores} worker processes to maximize CPU utilization...")
    processes = []
    for _ in range(cores):
        p = multiprocessing.Process(target=burn)
        p.start()
        processes.append(p)

    try:
        # Keep the main process alive
        for p in processes:
            p.join()
    except KeyboardInterrupt:
        for p in processes:
            p.terminate()
